-- Insert-only provisioning: existing keys, including edited starters, are never rewritten.
create unique index if not exists templates_workspace_starter_key
on public.templates (workspace_id, (data->>'starter_key'))
where data->>'starter_key' is not null;

create or replace function public.provision_starter_templates(p_workspace uuid, p_templates jsonb, p_retire_sample boolean default false)
returns integer language plpgsql security invoker set search_path = '' as $$
declare t jsonb; h text; template_id uuid; inserted integer := 0; affected integer;
begin
  for t in select value from jsonb_array_elements(p_templates) loop
    h := md5(p_workspace::text || ':' || (t->>'starter_key'));
    template_id := (substr(h,1,8)||'-'||substr(h,9,4)||'-4'||substr(h,14,3)||'-8'||substr(h,18,3)||'-'||substr(h,21,12))::uuid;
    insert into public.templates(id,workspace_id,data)
    values(template_id,p_workspace,t || jsonb_build_object('id',template_id))
    on conflict do nothing;
    get diagnostics affected = row_count;
    inserted := inserted + affected;
  end loop;
  if p_retire_sample then
    -- Patch metadata only. Never rewrite the old sample's content or clause 4.4.
    update public.templates set data = data || jsonb_build_object('name','Website proposal sample (old)','active',false)
    where workspace_id=p_workspace and id='00000000-0000-4000-8000-000000000020'
      and data->>'name'='Website proposal sample';
  end if;
  return inserted;
end $$;
revoke all on function public.provision_starter_templates(uuid,jsonb,boolean) from public,anon,authenticated;
grant execute on function public.provision_starter_templates(uuid,jsonb,boolean) to service_role;

